def followup_view(inputs, prior):
    packet=inputs.get('nineteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('nineteenth period packet changed')
    if prior is None or prior['counts']['after']!=118 or packet['prior_digest']!=digest(prior):raise ValueError('nineteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('nineteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=17 or len(packet['sources'])!=17 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('nineteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('nineteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('nineteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('nineteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('nineteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('nineteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('nineteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('nineteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('nineteenth period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('nineteenth period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
            if row['quarter_basis']!=expected:raise ValueError('nineteenth period quarter label changed')
        elif row['quarter_basis']!='nine_month_minus_h1':raise ValueError('nineteenth period derived quarter label changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace('\n','').replace(' ','')
            if any(row[k]not in text for k in keys):raise ValueError('nineteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('nineteenth period windows changed')
    conflicts=[(r['symbol'],r['metric'],r['quarter_difference_yuan'])for r in FINANCIAL if r['quarter_basis']=='reported_and_difference_conflict']
    if conflicts!=[('600581','recurring_profit','0.01')]:raise ValueError('nineteenth preserved financial difference changed')
    result={'through': '2026-11-19', 'title': '回款、执行与融资推进后，经营也改善了吗？', 'answer': '中珠已有部分占款回款，剩余占款与经营亏损保留；复华履行了借款案义务，再审仍在审查。八钢交易所审核通过，注册与发行实收仍待，季度亏损和现金另看；莫高现金改善与处置收益分开，不能合写全面修复。', 'counts': {'files': 17, 'new_files': 17, 'reused_files': 0, 'pages': 719, 'new_pages': 719, 'viewed_pages': 25, 'initial_coverage': 118, 'complete_windows': 47, 'unfinished_windows': 4, 'stock_endpoint_gaps': 0}, 'boundary': '129条目录、17份719页中核25关键页；未认证全文或全部催化。51窗口47满4未满，64独立股票端点核；36共同阶段40端点，不重复计经验。16财务14直接中13差额相符、八钢扣非0.01元差异保留，2现金单季另算。中珠8月回款不倒填半年期末；复华履约不当债权回收，再审审查不当改判；审批不当到账或经营修复。旧专题、冲突与缺口保持，不晋级经验。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,phase_comparisons=PHASES,event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
